function holidayFor(date=new Date()){const y=date.getFullYear(),m=date.getMonth()+1,d=date.getDate(),key=m*100+d,easter=easterDate(y),daysFromEaster=Math.round((new Date(y,m-1,d)-easter)/86400000),thanksgiving=nthWeekday(y,10,4,4),mothers=nthWeekday(y,4,0,2),fathers=nthWeekday(y,5,0,3);if(key>=1231||key<=102)return{name:'New Year',icon:'✦',theme:'newyear'};if(key>=212&&key<=214)return{name:"Valentine's Day",icon:'♥',theme:'valentine'};if(key>=316&&key<=317)return{name:"St. Patrick's Day",icon:'☘',theme:'patrick'};if(daysFromEaster>=-2&&daysFromEaster<=1)return{name:'Easter',icon:'❀',theme:'easter'};if(key===422)return{name:'Earth Day',icon:'●',theme:'earth'};if(date.toDateString()===mothers.toDateString())return{name:"Mother's Day",icon:'✿',theme:'mothers'};if(date.toDateString()===fathers.toDateString())return{name:"Father's Day",icon:'★',theme:'fathers'};if(key>=703&&key<=705)return{name:'Independence Day',icon:'★',theme:'independence'};if(key>=1025&&key<=1031)return{name:'Halloween',icon:'☾',theme:'halloween'};if(date>=thanksgiving&&date<=new Date(y,10,thanksgiving.getDate()+3))return{name:'Thanksgiving',icon:'◆',theme:'thanksgiving'};if(key>=1215&&key<=1230)return{name:'Winter Holidays',icon:'❄',theme:'winter'};return null}
