const CATALOG_CACHE='mase-catalog-v1',FLY_WEIGHTS='mase-flybrain-v1',FLY_CELLS=128;
let flyWeights=(()=>{try{const value=JSON.parse(storage.getItem(FLY_WEIGHTS)||'{}');return value&&typeof value==='object'?value:{}}catch{return {}}})();
function catalogFromCache(){try{const saved=JSON.parse(storage.getItem(CATALOG_CACHE)||'null');return saved&&Date.now()-saved.at<604800000&&Array.isArray(saved.tracks)?saved.tracks:[]}catch{return []}}
function setCatalog(items){state.tracks=items;trackIndex=new Map(items.map(t=>[String(t.id),t]))}
function saveCatalog(items){storage.setItem(CATALOG_CACHE,JSON.stringify({at:Date.now(),tracks:items.slice(0,2500).map(({liked,_score,...t})=>({...t,liked:false,plays:0}))}))}
function flyHash(value){let hash=2166136261;for(let i=0;i<value.length;i++){hash^=value.charCodeAt(i);hash=Math.imul(hash,16777619)}return hash>>>0}
function flyCells(track){const words=`${track.title||''} ${track.artist||''} ${track.album||''}`.toLowerCase().match(/[a-z0-9]{3,}/g)||[],tokens=[`artist:${track.artist||''}`,`album:${track.album||''}`,...words.slice(0,12)],cells=new Set();for(const token of tokens)for(let salt=0;salt<3;salt++)cells.add(flyHash(`${salt}:${token}`)%FLY_CELLS);return [...cells]}
function teachFly(track,reward){if(!track||!Number.isFinite(reward))return;for(const cell of flyCells(track)){const next=Math.max(-8,Math.min(12,Number(flyWeights[cell]||0)+reward));if(Math.abs(next)<.01)delete flyWeights[cell];else flyWeights[cell]=Number(next.toFixed(2))}storage.setItem(FLY_WEIGHTS,JSON.stringify(flyWeights));updateFlyStatus()}
function flyScore(track){const learned=flyCells(track).reduce((sum,cell)=>sum+Number(flyWeights[cell]||0),0),recentIndex=state.recent.indexOf(String(track.id)),novelty=recentIndex<0?2:-Math.max(0,5-recentIndex),popular=Math.log10(1+Number(track.plays||0))*.25;return learned+novelty+popular+Math.random()*2.2}
function flyPicks(limit=40){const excluded=new Set([state.currentId,...state.recent.slice(0,5)]),pool=state.tracks.filter(t=>!excluded.has(String(t.id)));return (pool.length?pool:state.tracks).map(t=>({t,score:flyScore(t)})).sort((a,b)=>b.score-a.score).slice(0,limit).map(x=>x.t)}
function updateFlyStatus(){const learned=Object.keys(flyWeights).length,status=$('#flyStatus');if(status)status.textContent=learned?`${learned} taste connections learned on this device.`:'Play, finish, skip, and like songs so VibeMind can learn.';const button=$('#flyBrain');if(button){button.classList.toggle('active',state.flyMode);button.textContent=state.flyMode?'⚡ VibeMind on':'⚡ VibeMind Radio'}}
function startFlyBrain(){if(!state.tracks.length)return toast('The music library is still loading.');state.flyMode=true;state.shuffle=false;state.queue=flyPicks();state.queuePos=0;updateFlyStatus();playTrack(state.queue[0],{keepQueue:true});toast('VibeMind is learning your taste.')}
function connectionAllowsWarmup(){const c=navigator.connection;return !c?.saveData&&!['slow-2g','2g'].includes(c?.effectiveType)}
function warmNext(){if(!connectionAllowsWarmup()||document.hidden||!state.queue.length)return;const next=byId(state.queue[(state.queuePos+1)%state.queue.length]);if(!next||next.audioUrl===audio.src||next.audioUrl===warmedUrl)return;warmedUrl=next.audioUrl;warmAudio.src=warmedUrl;warmAudio.load()}
function seededRandom(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function seededShuffle(items,seed){const random=seededRandom(seed),copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function stationTracks(name){if(name==='top')return [...state.tracks].sort((a,b)=>(b.plays||0)-(a.plays||0)).slice(0,100);if(name==='fresh')return [...state.tracks].sort((a,b)=>Number(b.id)-Number(a.id)).slice(0,100);return state.tracks}
function stationName(name){return name==='top'?'Top Hits':name==='fresh'?'Fresh Air':'Mase FM'}
function startRadio(name){const tracks=stationTracks(name);if(!tracks.length)return toast('The station is waiting for music.');const block=Math.floor(Date.now()/900000),seed=flyHash(`${name}:${block}`);state.radioStation=name;state.radioVoicePlaying=false;state.radioSongsUntilVoice=3+seed%3;state.flyMode=false;state.shuffle=false;state.repeat=0;state.queue=seededShuffle(tracks,seed).map(t=>String(t.id));state.queuePos=0;$('#shuffle').classList.remove('active');$('#repeat').classList.remove('active');$('sup',$('#repeat')).textContent='off';updateFlyStatus();updateRadioStatus();playTrack(state.queue[0],{keepQueue:true,radio:true});toast(`${stationName(name)} is live — everyone gets this lineup.`)}
async function playRadioVoice(){if(!state.radioVoiceLines.length)return false;const seed=flyHash(`${state.radioStation}:${Math.floor(Date.now()/900000)}:${state.queuePos}`),line=state.radioVoiceLines[seed%state.radioVoiceLines.length];state.radioVoicePlaying=true;state.currentId=null;pendingSeek=0;audio.src=line.audioUrl;$('#player').classList.remove('disabled');$('#nowTitle').textContent=line.label;$('#nowArtist').textContent=`${stationName(state.radioStation)} · Station voice`;$('#mini').style.backgroundImage='';$('#mini').textContent='●';if('mediaSession'in navigator)navigator.mediaSession.metadata=new MediaMetadata({title:line.label,artist:stationName(state.radioStation),album:'Live radio'});try{await audio.play();return true}catch{return false}}
function updateRadioStatus(){const status=$('#radioStatus');if(status){status.textContent=state.radioStation?`● Live on ${stationName(state.radioStation)}`:'● Same lineup for everyone';status.classList.toggle('on-air',Boolean(state.radioStation))}}
function renderVoiceLines(){const box=$('#radioVoiceLines');if(!box)return;box.innerHTML=state.radioVoiceLines.map(x=>`<div class="admin-track"><div><b>${esc(x.label)}</b><small>${Number(x.duration||0).toFixed(1)} sec</small></div><button class="danger" data-delete-voice="${attr(x.id)}">Delete</button></div>`).join('')||'<p class="muted">No voice lines yet. Add about 20 for a natural rotation.</p>'}
function audioDuration(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),probe=new Audio();probe.preload='metadata';probe.onloadedmetadata=()=>{const duration=probe.duration;URL.revokeObjectURL(url);Number.isFinite(duration)&&duration>0?resolve(duration):reject(Error('Could not read the voice-line duration.'))};probe.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not read that audio file.'))};probe.src=url})}
async function load(){
  api('/api/site-settings').then(r=>applySiteSettings(r.settings)).catch(()=>applyHoliday(true));
  const meTask=api('/api/auth/me').then(me=>{state.user=me.user;authUI();return me});
  const publicTask=api('/api/public/playlists').catch(()=>({playlists:[]}));
  api('/api/radio').then(r=>{state.radioVoiceLines=r.voiceLines||[];renderVoiceLines()}).catch(()=>{});
  const cached=catalogFromCache();if(cached.length&&!state.tracks.length){setCatalog(cached);restoreSession();render()}
  const tracks=await api('/api/tracks');setCatalog(tracks.tracks);saveCatalog(tracks.tracks);restoreSession();render();
  const trackMatch=location.pathname.match(/^\/track\/(\d+)$/);
  if(trackMatch&&byId(trackMatch[1])){openTrack(trackMatch[1],false);if(new URLSearchParams(location.search).get('play')==='1')playTrack(trackMatch[1])}
  await meTask;
  await Promise.allSettled([
    api('/api/track-stats').then(stats=>{const likes=new Set(stats.liked);state.tracks.forEach(t=>{t.plays=stats.plays[t.id]||0;t.liked=likes.has(String(t.id))});render()}),
    publicTask.then(publics=>{state.publicPlaylists=publics.playlists.map(x=>({...x,isPublic:true,trackIds:(x.trackIds||[]).map(String)}));renderTop();renderAdmin();const m=location.pathname.match(/^\/playlist\/(\d+)$/);if(m)openPlaylist(m[1],false)}),
    (state.user?api('/api/playlists'):Promise.resolve({playlists:[]})).then(p=>{state.playlists=p.playlists.map(x=>({...x,trackIds:(x.trackIds||[]).map(String)}));renderPlaylists();$('#playlistCount').textContent=state.playlists.length})
  ]);
}
function addRecent(id){state.recent=[String(id),...state.recent.filter(x=>String(x)!==String(id))].slice(0,12);storage.setItem('mase-recent',JSON.stringify(state.recent))}
async function playTrack(id,{keepQueue=false,radio=false}={}){
  const t=byId(id);if(!t)return toast('That song is unavailable.');
  if(!radio){state.radioStation=null;state.radioVoicePlaying=false;updateRadioStatus()}
  const previous=byId(state.currentId);if(previous&&String(previous.id)!==String(id)&&audio.currentTime>2&&!audio.ended&&(!Number.isFinite(audio.duration)||audio.currentTime<Math.min(30,audio.duration*.25)))teachFly(previous,-.7);
  if(!keepQueue){state.queue=state.tracks.map(x=>String(x.id));state.queuePos=state.queue.indexOf(String(id))}
  const version=++playbackVersion;state.currentId=String(id);state.repeatsDone=0;clearTimeout(playCountTimer);
  pendingSeek=0;audio.src=t.audioUrl;
  $('#player').classList.remove('disabled');$('#nowTitle').textContent=t.title;$('#nowArtist').textContent=t.artist;$('#play').textContent='…';
  $('#mini').style.backgroundImage=t.coverUrl?`url("${t.coverUrl.replaceAll('"','%22')}")`:'';$('#mini').textContent=t.coverUrl?'':'♫';
  addRecent(id);renderQueue();$('#recent').innerHTML=state.recent.map(byId).filter(Boolean).map(trackCard).join('');$('#recentCount').textContent=state.recent.length;
  if('mediaSession'in navigator)navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.album||'',artwork:t.coverUrl?[{src:t.coverUrl}]:[]});
  try{await audio.play();setTimeout(warmNext,900)}catch(error){if(version===playbackVersion&&error.name!=='AbortError'){toast('Tap play to start the song.');$('#play').textContent='▶'}}
}

async function recordPlay(id){const last=state.countedAt.get(String(id))||0;if(Date.now()-last<30000)return;state.countedAt.set(String(id),Date.now());try{const r=await api(`/api/tracks/${id}/play`,{method:'POST',body:'{}'}),t=byId(id);if(t)t.plays=r.plays;renderTop()}catch{}}
function startCollection(tracks,startId){if(!tracks.length)return toast('There are no songs here yet.');state.queue=tracks.map(t=>String(t.id));if(state.shuffle)shuffleArray(state.queue);state.queuePos=Math.max(0,state.queue.indexOf(String(startId||state.queue[0])));playTrack(state.queue[state.queuePos],{keepQueue:true})}
function next(){if(!state.queue.length)return;if(state.radioStation){if(state.radioVoicePlaying){state.radioVoicePlaying=false}else if(--state.radioSongsUntilVoice<=0&&state.radioVoiceLines.length){state.radioSongsUntilVoice=3+flyHash(`${state.radioStation}:${state.queuePos}`)%3;playRadioVoice();return}}if(state.flyMode&&state.queuePos>=state.queue.length-4){const used=new Set(state.queue),more=flyPicks(30).filter(t=>!used.has(String(t.id)));state.queue.push(...more.map(t=>String(t.id)))}state.queuePos=(state.queuePos+1+state.queue.length)%state.queue.length;playTrack(state.queue[state.queuePos],{keepQueue:true,radio:Boolean(state.radioStation)})}
function previous(){if(!state.queue.length)return;if(audio.currentTime>4){audio.currentTime=0;return}state.queuePos=(state.queuePos-1+state.queue.length)%state.queue.length;playTrack(state.queue[state.queuePos],{keepQueue:true,radio:Boolean(state.radioStation)})}
function openTrack(id,push=true){const t=byId(id);if(!t)return;$('#trackPage').innerHTML=`<div class="track-detail"><div class="detail-cover" ${coverStyle(t)}>${t.coverUrl?'':'♫'}</div><div><span class="eyebrow">TRACK</span><h1>${esc(t.title)}</h1><h2>${esc(t.artist)}</h2><p class="muted">${esc(t.album||'Single')} · ${esc(CONFIG.siteName)}</p><p class="play-total">▶ ${playLabel(t.plays)}</p><div class="detail-actions"><button class="primary" data-play="${t.id}">▶ Play now</button><button class="outline" data-play-next="${t.id}">Play next</button><button class="outline" data-queue-add="${t.id}">＋ Queue</button><button class="outline" data-like="${t.id}">${t.liked?'♥ Liked':'♡ Like'}</button><button class="outline" data-add-menu="${t.id}">＋ Playlist</button><button class="outline" data-share="${t.id}">↗ Share & play</button></div></div></div>`;if(!$('#trackDialog').open)$('#trackDialog').showModal();if(push)history.pushState({track:id},'',`/track/${id}`)}
function closeTrack(){if($('#trackDialog').open)$('#trackDialog').close();if(location.pathname.startsWith('/track/'))history.pushState({},'','/')}
function openPlaylist(id,push=true){const p=findPlaylist(id);if(!p)return;const songs=p.trackIds.map(byId).filter(Boolean),canEdit=!p.isMix&&(!p.isPublic||state.user?.isAdmin);$('#playlistPage').innerHTML=`<span class="eyebrow">${p.isMix?'AUTOMATIC MIX':p.isPublic?'PUBLIC PLAYLIST':'PLAYLIST'}</span><h1>${esc(p.name)}</h1><p class="muted">${songs.length} song${songs.length===1?'':'s'}</p><div class="detail-actions"><button class="primary" data-play-playlist="${p.id}">▶ Play playlist</button><button class="outline" data-shuffle-playlist="${p.id}">Shuffle</button><button class="outline" data-queue-playlist="${p.id}">＋ Queue all</button>${canEdit?`<button class="outline" data-pick-tracks="${p.id}">＋ Add songs</button>`:''}${p.isPublic?`<button class="outline" data-share-playlist="${p.id}">↗ Share</button>`:''}</div><div>${songs.map(t=>`<div class="playlist-track"><div><b>${esc(t.title)}</b><small>${esc(t.artist)} · ${playLabel(t.plays)}</small></div><button data-play="${t.id}">▶</button>${canEdit?`<button data-remove-from="${p.id}" data-track="${t.id}">Remove</button>`:''}</div>`).join('')||'<p class="muted">Open any song and tap “Playlist” to add it here.</p>'}</div>`;if(!$('#playlistDialog').open)$('#playlistDialog').showModal();if(push&&p.isPublic)history.pushState({playlist:id},'',`/playlist/${id}`)}
async function createPlaylist(isPublic=false){if(!requireUser('Log in to create playlists.'))return;if(isPublic&&!state.user?.isAdmin)return;const values=await uiAsk({title:isPublic?'Create public playlist':'Create a playlist',message:isPublic?'Everyone will be able to open and share this playlist.':'Give your new playlist a name.',confirm:'Create playlist',fields:[{name:'name',label:'Playlist name'}]});if(!values)return;try{const r=await api(isPublic?'/api/admin/public-playlists':'/api/playlists',{method:'POST',body:JSON.stringify(values)});(isPublic?state.publicPlaylists:state.playlists).unshift({...r.playlist,isPublic,trackIds:[]});render();toast(isPublic?'Public playlist created.':'Playlist created.')}catch(e){toast(e.message)}}
async function toggleLike(id){if(!requireUser('Create a free account to save this song.'))return;try{const r=await api(`/api/tracks/${id}/like`,{method:'POST',body:'{}'}),t=byId(id);t.liked=r.liked;teachFly(t,r.liked?2.5:-2);render();if($('#trackDialog').open)openTrack(id,false)}catch(e){toast(e.message)}}
async function choosePlaylist(trackId){if(!requireUser('Log in to add songs to playlists.'))return;const choices=[...state.playlists,...(state.user?.isAdmin?state.publicPlaylists:[])];if(!choices.length){toast('Create a playlist first.');return createPlaylist()}const values=await uiAsk({title:'Add to playlist',message:'Choose where this song should go.',confirm:'Add song',fields:[{name:'playlistId',label:'Playlist',type:'select',options:choices.map(p=>({value:p.id,label:`${p.name}${p.isPublic?' (Public)':''}`}))}]});if(!values)return;const p=choices.find(x=>String(x.id)===String(values.playlistId));try{await api(`/api/playlists/${p.id}/tracks`,{method:'POST',body:JSON.stringify({trackId})});if(!p.trackIds.includes(String(trackId)))p.trackIds.push(String(trackId));render();toast(`Added to ${p.name}.`)}catch(e){toast(e.message)}}
async function shareContent({title,text,url}){try{if(navigator.share){await navigator.share({title,text,url});return}await navigator.clipboard.writeText(url);toast('Link copied!')}catch(e){if(e.name!=='AbortError')uiAsk({title:'Copy this link',message:'Select and copy the link below.',confirm:'Done',fields:[{name:'link',label:'Song or playlist link',value:url,maxlength:2000}]})}}
async function loadGithubMusic(){const select=$('#githubMusicFile');select.innerHTML='<option>Loading files…</option>';try{const r=await api('/api/admin/github-music'),files=r.files.filter(x=>!x.registered);select.innerHTML='<option value="">Choose a song file</option>'+files.map(x=>`<option value="${esc(x.path)}">${esc(x.name)} (${(x.size/1048576).toFixed(1)} MB)</option>`).join('');if(!files.length)select.innerHTML='<option value="">No unregistered audio files</option>'}catch(e){select.innerHTML='<option>Could not load files</option>';toast(e.message)}}
async function loadRequests(){try{const r=await api('/api/admin/requests');state.requests=r.requests;renderRequests()}catch(e){toast(e.message)}}
function renderRequests(){if(!state.user?.isAdmin)return;const list=state.requestFilter==='all'?state.requests:state.requests.filter(x=>(x.status||'new')===state.requestFilter);$('#requests').innerHTML=list.map(x=>`<article class="request request-card"><div><div class="request-title"><b>${esc(x.song)}${x.artist?` — ${esc(x.artist)}`:''}</b><span class="status status-${attr(x.status||'new')}">${esc(x.status||'new')}</span></div><small>${esc(x.notes||'No notes')}</small><small>Requested by ${esc(x.nickname||x.user_email||'Guest')} · ${new Date(x.created_at).toLocaleDateString()}</small></div><select data-request-status="${x.id}" aria-label="Status for ${attr(x.song)}"><option value="new" ${(x.status||'new')==='new'?'selected':''}>New</option><option value="reviewing" ${x.status==='reviewing'?'selected':''}>Reviewing</option><option value="added" ${x.status==='added'?'selected':''}>Added</option><option value="declined" ${x.status==='declined'?'selected':''}>Declined</option></select><button class="danger" data-delete-request="${x.id}">Delete</button></article>`).join('')||'<p class="muted">No requests in this view.</p>'}
async function loadAdmin(){await Promise.allSettled([loadRequests(),loadGithubMusic(),api('/api/admin/overview').then(x=>{$('#adminUserCount').textContent=x.users.toLocaleString();$('#adminRequestCount').textContent=x.newRequests.toLocaleString();$('#adminPlayCount').textContent=x.plays.toLocaleString()})]);renderAdmin();fillSettingsForm()}
function openAdminTab(name){$$('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x.dataset.adminTab===name));$$('[data-admin-pane]').forEach(x=>x.classList.toggle('active',x.dataset.adminPane===name))}
function navigate(page){if(page==='library'&&!requireUser('Log in to open your personal library.'))return;if(page==='admin'&&!state.user?.isAdmin)return toast('Admin access only.');$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$$('.page').forEach(x=>x.classList.remove('active'));$(`#${page}Page`).classList.add('active');$('#sidebar').classList.remove('open');if(page==='admin')loadAdmin()}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-open-playlist]');if(!el)return;const d=el.dataset;
  if(d.radio)startRadio(d.radio);
  if(d.searchTrack){const t=byId(d.searchTrack);saveSearch(state.query||t.title);hideSearch();openTrack(t.id)}if(d.searchQuery!==undefined){state.query=decodeURIComponent(d.searchQuery);$('#search').value=state.query;render();showSearch()}if(d.clearHistory!==undefined){state.recentSearches=[];storage.removeItem('mase-searches');renderSearch()}
  if(d.pickTracks)openSongPicker(d.pickTracks);
  if(d.adminTab)openAdminTab(d.adminTab);if(d.adminJump)openAdminTab(d.adminJump);
  if(d.pickerAdd){const button=el,playlistId=activePicker;button.disabled=true;try{await api(`/api/playlists/${playlistId}/tracks`,{method:'POST',body:JSON.stringify({trackId:d.pickerAdd})});const p=findPlaylist(playlistId);if(p&&!p.trackIds.includes(String(d.pickerAdd)))p.trackIds.push(String(d.pickerAdd));renderPicker();renderPlaylists();renderTop();renderAdmin()}catch(error){button.disabled=false;toast(error.message)}}
  if(d.playNext){state.queue.splice(Math.max(0,state.queuePos+1),0,String(d.playNext));renderQueue();toast('Playing next.')}
  if(d.page)navigate(d.page);if(d.play)playTrack(d.play);if(d.openTrack)openTrack(d.openTrack);if(d.like)toggleLike(d.like);if(d.queueAdd){state.queue.push(String(d.queueAdd));renderQueue();toast('Added to queue.')}if(d.addMenu)choosePlaylist(d.addMenu);if(d.openPlaylist)openPlaylist(d.openPlaylist);
  if(d.playPlaylist){const p=findPlaylist(d.playPlaylist);if(p){state.shuffle=false;$('#shuffle').classList.remove('active');startCollection(p.trackIds.map(byId).filter(Boolean))}}
  if(d.shufflePlaylist){const p=findPlaylist(d.shufflePlaylist);if(p){state.shuffle=true;$('#shuffle').classList.add('active');startCollection(p.trackIds.map(byId).filter(Boolean))}}
  if(d.queuePlaylist){const p=findPlaylist(d.queuePlaylist);if(p){state.queue.push(...p.trackIds.filter(byId).map(String));renderQueue();toast('Playlist added to queue.')}}
  if(d.queueJump!==undefined){state.queuePos=Number(d.queueJump);playTrack(state.queue[state.queuePos],{keepQueue:true})}
  if(d.queueUp!==undefined){const i=Number(d.queueUp);if(i>state.queuePos+1){[state.queue[i-1],state.queue[i]]=[state.queue[i],state.queue[i-1]];renderQueue()}}
  if(d.removeFrom){try{await api(`/api/playlists/${d.removeFrom}/tracks/${d.track}`,{method:'DELETE'});const p=[...state.playlists,...state.publicPlaylists].find(x=>String(x.id)===String(d.removeFrom));p.trackIds=p.trackIds.filter(x=>String(x)!==String(d.track));openPlaylist(p.id,false);render();toast('Removed from playlist.')}catch(x){toast(x.message)}}
  if(d.renamePlaylist){e.stopPropagation();const p=[...state.playlists,...state.publicPlaylists].find(x=>String(x.id)===String(d.renamePlaylist));const values=await uiAsk({title:'Rename playlist',message:'Choose a name that is easy to recognize.',confirm:'Save name',fields:[{name:'name',label:'Playlist name',value:p.name}]});if(values?.name.trim())try{await api(`/api/playlists/${p.id}`,{method:'PATCH',body:JSON.stringify(values)});p.name=values.name.trim();render();toast('Playlist renamed.')}catch(x){toast(x.message)}}
  if(d.deletePlaylist){e.stopPropagation();const p=[...state.playlists,...state.publicPlaylists].find(x=>String(x.id)===String(d.deletePlaylist));const ok=await uiAsk({title:'Delete this playlist?',message:`“${p?.name||'This playlist'}” will be permanently removed.`,confirm:'Delete playlist',danger:true});if(ok)try{await api(`/api/playlists/${d.deletePlaylist}`,{method:'DELETE'});state.playlists=state.playlists.filter(x=>String(x.id)!==String(d.deletePlaylist));state.publicPlaylists=state.publicPlaylists.filter(x=>String(x.id)!==String(d.deletePlaylist));render();toast('Playlist deleted.')}catch(x){toast(x.message)}}
  if(d.queueRemove!==undefined){const i=Number(d.queueRemove);if(i!==state.queuePos){state.queue.splice(i,1);if(i<state.queuePos)state.queuePos--;renderQueue()}}
  if(d.share){const t=byId(d.share);shareContent({title:`${t.title} — ${t.artist}`,text:`Listen to ${t.title} by ${t.artist} on ${CONFIG.siteName}`,url:`${location.origin}/track/${t.id}?play=1`})}
  if(d.sharePlaylist){e.stopPropagation();const p=state.publicPlaylists.find(x=>String(x.id)===String(d.sharePlaylist));if(p)shareContent({title:p.name,text:`Listen to ${p.name} on ${CONFIG.siteName}`,url:`${location.origin}/playlist/${p.id}`})}
  if(d.editTrack){const t=byId(d.editTrack),values=await uiAsk({title:'Edit track details',message:'These changes appear everywhere on the site.',confirm:'Save changes',fields:[{name:'title',label:'Title',value:t.title},{name:'artist',label:'Artist',value:t.artist},{name:'album',label:'Album',value:t.album||'',required:false},{name:'coverUrl',label:'HTTPS cover URL',type:'url',value:t.coverUrl||'',required:false,maxlength:500}]});if(!values)return;try{await api(`/api/admin/tracks/${t.id}`,{method:'PATCH',body:JSON.stringify(values)});Object.assign(t,values);render();toast('Track updated.')}catch(x){toast(x.message)}}
  if(d.deleteTrack){const t=byId(d.deleteTrack),ok=await uiAsk({title:'Delete this song?',message:`“${t?.title||'This song'}” and its audio file will be permanently removed.`,confirm:'Delete song',danger:true});if(ok)try{await api(`/api/admin/tracks/${d.deleteTrack}`,{method:'DELETE'});state.tracks=state.tracks.filter(x=>String(x.id)!==String(d.deleteTrack));trackIndex.delete(String(d.deleteTrack));render();toast('Track deleted.')}catch(x){toast(x.message)}}
  if(d.deleteVoice){const line=state.radioVoiceLines.find(x=>String(x.id)===String(d.deleteVoice)),ok=await uiAsk({title:'Delete this voice line?',message:`“${line?.label||'This voice line'}” will be removed from the station.`,confirm:'Delete voice line',danger:true});if(ok)try{await api(`/api/admin/radio/voice-lines/${d.deleteVoice}`,{method:'DELETE'});state.radioVoiceLines=state.radioVoiceLines.filter(x=>String(x.id)!==String(d.deleteVoice));renderVoiceLines();toast('Voice line deleted.')}catch(x){toast(x.message)}}
  if(d.deleteRequest){const item=state.requests.find(x=>String(x.id)===String(d.deleteRequest)),ok=await uiAsk({title:'Delete this request?',message:item?`“${item.song}” will be permanently removed.`:'This request will be permanently removed.',confirm:'Delete request',danger:true});if(ok)try{await api(`/api/admin/requests/${d.deleteRequest}`,{method:'DELETE'});state.requests=state.requests.filter(x=>String(x.id)!==String(d.deleteRequest));renderRequests();toast('Request deleted.')}catch(x){toast(x.message)}}
});
document.addEventListener('change',async e=>{if(!e.target.dataset.requestStatus)return;try{const r=await api(`/api/admin/requests/${e.target.dataset.requestStatus}`,{method:'PATCH',body:JSON.stringify({status:e.target.value})}),item=state.requests.find(x=>String(x.id)===String(r.request.id));if(item)item.status=r.request.status;renderRequests();toast('Request status updated.')}catch(x){toast(x.message)}});
audio.addEventListener('timeupdate',()=>{$('#current').textContent=fmt(audio.currentTime);$('#duration').textContent=fmt(audio.duration);$('#seek').value=audio.duration?Math.round(audio.currentTime/audio.duration*1000):0});
audio.addEventListener('playing',()=>{clearTimeout(playCountTimer);const id=state.currentId;setTimeout(warmNext,900);playCountTimer=setTimeout(()=>{if(!audio.paused&&state.currentId===id){recordPlay(id);teachFly(byId(id),.2)}},10000)});audio.addEventListener('waiting',()=>clearTimeout(playCountTimer));audio.addEventListener('play',()=>{$('#play').textContent='❚❚';$('.vinyl')?.classList.add('playing')});audio.addEventListener('pause',()=>{clearTimeout(playCountTimer);$('#play').textContent='▶';$('.vinyl')?.classList.remove('playing')});
audio.addEventListener('ended',()=>{teachFly(byId(state.currentId),1);if(state.repeat===Infinity||state.repeatsDone<state.repeat){state.repeatsDone++;teachFly(byId(state.currentId),.4);audio.currentTime=0;audio.play()}else next()});
$('#play').onclick=()=>{if(!state.currentId&&!audio.src)return startCollection(filteredTracks());audio.paused?audio.play().catch(()=>toast('Playback could not start. Try another song.')):audio.pause()};$('#next').onclick=next;$('#prev').onclick=previous;$('#heroPlay').onclick=()=>startCollection(filteredTracks());$('#heroShuffle').onclick=()=>{state.shuffle=true;$('#shuffle').classList.add('active');startCollection(filteredTracks())};$('#surprise').onclick=()=>playTrack(state.tracks[Math.floor(Math.random()*state.tracks.length)]?.id);$('#volume').oninput=e=>{audio.volume=+e.target.value;storage.setItem('mase-volume',audio.volume)};$('#seek').oninput=e=>{if(audio.duration)audio.currentTime=+e.target.value/1000*audio.duration};
$('#repeat').onclick=()=>{const modes=[0,1,2,Infinity],i=(modes.indexOf(state.repeat)+1)%modes.length;state.repeat=modes[i];state.repeatsDone=0;storage.setItem('mase-repeat',String(state.repeat));$('#repeat').classList.toggle('active',state.repeat!==0);$('sup',$('#repeat')).textContent=state.repeat===Infinity?'∞':state.repeat?`${state.repeat}x`:'off';toast(state.repeat===Infinity?'Infinite loop':state.repeat?`Loop ${state.repeat} extra time${state.repeat===1?'':'s'}`:'Loop off')};
$('#shuffle').onclick=()=>{state.shuffle=!state.shuffle;state.flyMode=false;storage.setItem('mase-shuffle',String(state.shuffle));updateFlyStatus();if(state.shuffle){const tail=state.queue.slice(state.queuePos+1);shuffleArray(tail);state.queue.splice(state.queuePos+1,tail.length,...tail);renderQueue()}$('#shuffle').classList.toggle('active',state.shuffle);toast(state.shuffle?'Shuffle on':'Shuffle off')};$('#queueBtn').onclick=()=>$('#queuePanel').classList.add('open');$('#closeQueue').onclick=()=>$('#queuePanel').classList.remove('open');$('#clearQueue').onclick=()=>{state.queue=state.currentId?[state.currentId]:[];state.queuePos=0;renderQueue()};
