function party(){document.body.classList.toggle('party');for(let i=0;i<70;i++){const c=document.createElement('i');c.className='confetti';c.style.left=`${Math.random()*100}%`;c.style.background=`hsl(${Math.random()*360} 90% 60%)`;c.style.animationDelay=`${Math.random()}s`;$('#confetti').append(c);setTimeout(()=>c.remove(),3500)}toast(document.body.classList.contains('party')?`🎉 ${CONFIG.siteName} Mode unlocked!`:`${CONFIG.siteName} Mode off`)}
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable=true]')||document.querySelector('dialog[open]'))return;if(e.key==='/'){e.preventDefault();$('#search').focus();showSearch();return}if(e.target.matches('input,textarea'))return;typed=(typed+e.key.toLowerCase()).slice(-10);if(typed.endsWith('mase'))party();if(e.target.closest('button,a'))return;if(e.code==='Space'){e.preventDefault();$('#play').click()}if(e.key==='ArrowRight')next();if(e.key==='ArrowLeft')previous();if(e.key.toLowerCase()==='m')$('#mute').click();if(e.key.toLowerCase()==='f')startFlyBrain()});
