let sessionRestored=false,pendingSeek=0,lastSaved=0,activePicker=null;
function shuffleArray(items){for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function saveSession(){if(!sessionRestored)return;storage.setItem('mase-session',JSON.stringify({queue:state.queue.slice(0,2000),position:state.queuePos,current:state.currentId,time:pendingSeek||audio.currentTime||0}))}
function restoreSession(){
  if(sessionRestored)return;sessionRestored=true;
  try{const saved=JSON.parse(storage.getItem('mase-session')||'null');if(!saved||!Array.isArray(saved.queue))return;
    const queue=saved.queue.map(String);const pos=Number.isInteger(saved.position)?saved.position:-1;
    state.queue=queue.filter(byId).slice(0,2000);state.queuePos=queue.slice(0,pos).filter(byId).length;
    const t=byId(saved.current);if(!t){state.queuePos=-1;return}
    state.currentId=String(t.id);if(state.queue[state.queuePos]!==state.currentId)state.queuePos=state.queue.indexOf(state.currentId);
    pendingSeek=Number.isFinite(saved.time)?Math.max(0,saved.time):0;audio.preload='metadata';audio.src=t.audioUrl;
    $('#player').classList.remove('disabled');$('#nowTitle').textContent=t.title;$('#nowArtist').textContent=t.artist;$('#play').textContent='▶';toast('Your queue is ready. Press play to continue.');
  }catch{}
}
audio.addEventListener('loadedmetadata',()=>{if(pendingSeek&&Number.isFinite(audio.duration)){audio.currentTime=Math.min(pendingSeek,Math.max(0,audio.duration-1));pendingSeek=0}audio.preload='auto'});
audio.addEventListener('timeupdate',()=>{if(Date.now()-lastSaved>5000){lastSaved=Date.now();saveSession()}});
audio.addEventListener('pause',saveSession);window.addEventListener('pagehide',saveSession);
